mapper.select:
SELECT c.car_id AS carId, c.place_location_id AS placeLocationId, c.car_name AS carName, c.car_type AS carType, c.car_number AS carNumber, c.car_fuel_type AS fuelType, c.car_seats AS seats, c.car_price_per_day AS pricePerDay, c.car_image_url AS carImageUrl FROM tblRentalCar c JOIN tblPlaceLocation pl ON pl.place_location_id = c.place_location_id WHERE pl.place_location_name = #{region, jdbcType=VARCHAR} AND c.car_status = 'y'
AND c.car_type = #{carType, jdbcType=VARCHAR}
AND c.car_fuel_type = #{fuelType, jdbcType=VARCHAR}
AND c.car_seats = #{seats, jdbcType=INTEGER}
AND c.car_price_per_day <= #{maxPrice, jdbcType=INTEGER}
ORDER BY c.car_name
